    # law numbers_below_next (todo/laws.slg:9)
    # @why a number is never reused
    def self.numbers_below_next(t) = t.states.all? { |w| w.tasks.keys.all? { |it| it < w.next_no } }

    # law next_only_grows (todo/laws.slg:13)
    # @why only add moves the counter, and only up
    def self.next_only_grows(t) = t.steps.all? { |it| it.after.next_no >= it.before.next_no }

    # law others_untouched (todo/laws.slg:17)
    # @why a command that names a task touches no other task
    def self.others_untouched(t, k)
      t.steps.all? do |s|
        !(s.event.arg("no") != k) || Spec::Maps.get(s.after.tasks, k) == Spec::Maps.get(s.before.tasks, k)
      end
    end

    # law clear_keeps_every_open_task (todo/laws.slg:21)
    def self.clear_keeps_every_open_task(t)
      t.steps.all? do |s|
        !s.event.call_of?("todo.board.clear") ||
          s.after.tasks.values.all? { |it| it.status == Todo::Model::Status::Open } &&
            s.after.tasks.size == s.before.tasks.values.select { |it| it.status == Todo::Model::Status::Open }.size
      end
    end

    # law reads_change_nothing (todo/laws.slg:26)
    def self.reads_change_nothing(t) = t.steps.all? { |it| it.after == it.before }

    # law refusal_changes_nothing (todo/laws.slg:29)
    # @why a refused command leaves the board as it was
    def self.refusal_changes_nothing(t)
      t.steps.all? { |s| !s.reply.is_a?(Spec::Err) || s.after == s.before }
    end

    # law stored_under_its_number (todo/laws.slg:33)
    # @why a task is stored under its own number
    def self.stored_under_its_number(t)
